        def best_from_left(segs):
            segs.sort()
            n = len(segs)
            best = 0
            covered = 0
            j = 0
            for i in range(n):
                end = segs[i][0] + k - 1
                while j < n and segs[j][1] <= end:
                    covered += (segs[j][1] - segs[j][0] + 1) * segs[j][2]
                    j += 1
                partial = 0
                if j < n and segs[j][0] <= end:
                    partial = (end - segs[j][0] + 1) * segs[j][2]
                best = max(best, covered + partial)
                if j > i:
                    covered -= (segs[i][1] - segs[i][0] + 1) * segs[i][2]
